-- =====================================================================
-- CMS update 3: "Major achievements" cards (one per LGA, plus legislative duties).
-- Safe to run more than once.
-- =====================================================================

create table if not exists public.achievement_cards (
  id             uuid primary key default gen_random_uuid(),
  title          text not null,
  zone           text not null default '',
  heading        text not null default '10 major achievements',
  items          jsonb not null default '[]'::jsonb,   -- ["text", ...]
  extra_heading  text not null default '',
  extra_items    jsonb not null default '[]'::jsonb,   -- ["text", ...]
  published      boolean not null default true,
  sort_order     integer not null default 0,
  created_by     uuid references auth.users (id) on delete set null,
  updated_by     uuid references auth.users (id) on delete set null,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);

alter table public.achievement_cards enable row level security;

drop trigger if exists achievement_cards_audit on public.achievement_cards;
create trigger achievement_cards_audit before insert or update on public.achievement_cards
  for each row execute function public.touch_audit();

drop policy if exists "staff read all" on public.achievement_cards;
drop policy if exists "staff insert" on public.achievement_cards;
drop policy if exists "staff update" on public.achievement_cards;
drop policy if exists "staff delete" on public.achievement_cards;
drop policy if exists "public reads published achievements" on public.achievement_cards;
create policy "staff read all" on public.achievement_cards for select to authenticated using (public.is_staff(auth.uid()));
create policy "staff insert" on public.achievement_cards for insert to authenticated with check (public.is_staff(auth.uid()));
create policy "staff update" on public.achievement_cards for update to authenticated using (public.is_staff(auth.uid())) with check (public.is_staff(auth.uid()));
create policy "staff delete" on public.achievement_cards for delete to authenticated using (public.is_staff(auth.uid()));
create policy "public reads published achievements" on public.achievement_cards for select to anon, authenticated using (published);

-- Seed from the campaign flyers (only when the table is empty).
insert into public.achievement_cards (title, zone, heading, items, extra_heading, extra_items, sort_order)
select * from (values
  ($a0$Ogo Oluwa Local Government$a0$, $a1$Ogbomoso$a1$, $a2$10 major achievements$a2$, $a3$["Installation of 493 solar-powered streetlights across the ten wards.","Construction and equipping of primary health centres, health centres and places of worship across selected wards.","Scholarships and tuition support for vulnerable students in the ten wards.","Empowerment and training of youth in various trades and skills, with startup grants.","GSM repair training and empowerment for youth, with 24 beneficiaries in each of the ten wards.","Tractors and other farm implements distributed to support farmers and agripreneurs.","Medical outreach, free health checks and medicines for a total of 519 patients.","Rehabilitation of boreholes and solar-powered water schemes for various communities.","Sewing, hairdressing and makeup equipment, safety boots, power tools and other equipment for artisan groups.","Grinding machines, welding machines and complete automobile mechanic toolboxes."]$a3$::jsonb, $a4$$a4$, $a5$[]$a5$::jsonb, 0),
