  ($a18$Egbeda Local Government$a18$, $a19$Ibadan$a19$, $a20$10 major achievements$a20$, $a21$["721 solar-powered streetlights across 11 wards.","1 solar-powered borehole per ward (11 wards).","Tailoring skills training: 31 beneficiaries (sewing machines).","9 beneficiaries empowered with grinding machines.","GSM repair training: 24 youths (tool kits).","ICT training: 37 youths (Android tablets).","Medical outreach: 385 patients treated and ₦50,000 each for 32 beneficiaries.","3-day UN Women training on ending violence against women and girls (1 individual sponsored).","Construction of new classrooms at Olode Primary School.","Renovation of classrooms at 3 schools."]$a21$::jsonb, $a22$Schools renovated$a22$, $a23$["Egbeda Community High School","Asejire Primary School","Onikoko Primary School"]$a23$::jsonb, 30),
  ($a24$Lagelu Local Government$a24$, $a25$Ibadan$a25$, $a26$10 major achievements$a26$, $a27$["640 solar-powered streetlights across 14 wards.","1 solar-powered borehole per ward (14 wards).","Tailoring skills training: 35 beneficiaries (sewing machines).","9 beneficiaries empowered with grinding machines.","GSM repair training: 24 youths (tool kits).","ICT training: 42 youths (Android tablets).","Medical outreach: 362 patients treated and ₦50,000 each for 25 beneficiaries.","3-day UN Women training on ending violence against women and girls (1 individual sponsored).","Construction of new classrooms at Community Grammar School, Apatere.","Renovation of classrooms at 2 schools (Ejoku Senior and Junior Schools)."]$a27$::jsonb, $a28$Schools renovated$a28$, $a29$["Ejoku Senior Secondary School","Ejoku Junior Secondary School"]$a29$::jsonb, 40),
  ($a30$Ona-Ara Local Government$a30$, $a31$Ibadan$a31$, $a32$10 major achievements$a32$, $a33$["627 solar-powered streetlights across 11 wards, plus 1 extra borehole at Badeku Village (12 boreholes in total).","1 solar-powered borehole per ward (11 wards).","Tailoring skills training: 27 beneficiaries (sewing machines).","7 beneficiaries empowered with grinding machines.","GSM repair training: 23 youths (tool kits).","ICT training: 38 youths (Android tablets).","4 welding artisans and 4 automobile mechanics empowered.","Medical outreach: 265 patients treated and ₦50,000 each for 26 beneficiaries.","Construction of new classrooms at Christ Basic School, Bioku Etilo.","Renovation of classrooms at Aho Parapo Community Secondary School and Community High School, Airport."]$a33$::jsonb, $a34$Schools renovated$a34$, $a35$["Aho Parapo Community Secondary School","Community High School, Airport"]$a35$::jsonb, 50),
